import { createHash } from 'node:crypto';
import { gzip } from 'node:zlib';
import { promisify } from 'node:util';
import { MAX_DATASET_BYTES, MAX_URLS, type AuditResult, type PageRow, type ReportOptions } from './types.js';
import { reportBrowserMain, type ReportPayload } from './report-browser.js';

const compress = promisify(gzip);
const categories = { broken_links: 'Broken links', redirects: 'Redirects', canonicals: 'Canonicals & indexability', sitemaps: 'Sitemaps', metadata: 'Metadata' } as const;
const priorities = ['high', 'medium', 'low', 'info'] as const;
const escape = (value: unknown): string => String(value ?? '').replace(/[&<>"']/g, character => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[character]!);
const number = (value: number): string => value.toLocaleString('en-US');
const sha256 = (value: string): string => createHash('sha256').update(value).digest('base64');

/** Quote every cell and prevent spreadsheets from interpreting untrusted text as a formula. */
function csvCell(value: unknown): string {
  let text = value === null || value === undefined ? '' : String(value);
  if (/^[\s\uFEFF]*[=+\-@]/u.test(text) || /^[\t\r\n]/u.test(text)) text = `'${text}`;
  return `"${text.replace(/"/g, '""')}"`;
}
function csv(rows: unknown[][]): string { return rows.map(row => row.map(csvCell).join(',')).join('\r\n') + '\r\n'; }

/**
 * Count the exact UTF-8 JSON payload size one row/finding at a time. The fixed
 * envelope includes options, coverage, provenance, and the empty array tokens;
 * replacing those arrays adds each element plus only its separating comma.
 * The optional smaller budget is for tests. renderReport always uses the
 * shared production limit and exposes no override to an assistant.
 */
export function assertReportDatasetBudget(payload: ReportPayload, budget = MAX_DATASET_BYTES): number {
  if (!Number.isSafeInteger(budget) || budget < 1 || budget > MAX_DATASET_BYTES) throw new Error('Invalid report dataset byte budget.');
  let bytes = 0;
  const add = (value: unknown, comma = false): void => {
    bytes += Buffer.byteLength(JSON.stringify(value), 'utf8') + (comma ? 1 : 0);
    if (bytes > budget) throw new Error(`Report dataset exceeds the ${number(budget)}-byte uncompressed limit. Reduce the audited dataset or extracted metadata and start a fresh audit; no data was sampled.`);
  };
  add({ result: { ...payload.result, findings: [] }, pages: [], options: payload.options });
  for (let index = 0; index < payload.result.findings.length; index++) add(payload.result.findings[index], index > 0);
  for (let index = 0; index < payload.pages.length; index++) add(payload.pages[index], index > 0);
  return bytes;
}
function verify(result: AuditResult, pages: PageRow[], options: ReportOptions): void {
  if (pages.length > MAX_URLS || result.pageCount > MAX_URLS) throw new Error(`Reports support at most ${number(MAX_URLS)} URLs; no data is sampled.`);
  if (!Number.isSafeInteger(result.pageCount) || result.pageCount !== pages.length) throw new Error('Report page count must reconcile with the complete snapshot.');
  const ids = new Set<number>();
  for (const page of pages) {
    if (!Number.isSafeInteger(page.id) || page.id < 0 || ids.has(page.id)) throw new Error('Snapshot page IDs must be unique non-negative integers.');
    ids.add(page.id);
  }
  const findingIds = new Set<string>();
  for (const finding of result.findings) {
    if (!finding.id || findingIds.has(finding.id)) throw new Error('Finding IDs must be non-empty and unique.');
    findingIds.add(finding.id);
    if (!Object.hasOwn(categories, finding.category) || !priorities.includes(finding.priority)) throw new Error('Unknown finding category or priority.');
    if (finding.affectedCount !== finding.affectedIds.length || new Set(finding.affectedIds).size !== finding.affectedCount || finding.affectedIds.some(id => !ids.has(id))) throw new Error(`Finding ${finding.id} does not reconcile with snapshot evidence.`);
  }
  const references = new Set<string>();
  for (const item of options.narrative?.findings ?? []) {
    if (!findingIds.has(item.findingId)) throw new Error(`Narrative refers to unknown finding: ${item.findingId}`);
    if (references.has(item.findingId)) throw new Error(`Narrative repeats finding: ${item.findingId}`);
    references.add(item.findingId);
  }
}

