export async function renderReport(result: AuditResult, pages: PageRow[], options: ReportOptions = {}): Promise<{ html: string; findingsCsv: string; urlsCsv: string }> {
  verify(result, pages, options);
  const payload: ReportPayload = { result, pages, options };
  assertReportDatasetBudget(payload);
  const compressed = (await compress(JSON.stringify(payload), { level: 6 })).toString('base64');
  // tsx preserves function names using a generated __name helper. Provide that
  // helper inside the standalone script so source-mode reports work as well as
  // the production bundle, without reaching outside this offline document.
  const script = `(()=>{const __name=(fn)=>fn;const dataset=${JSON.stringify(compressed)};(${reportBrowserMain.toString()})(dataset);})();`;
  const csp = `default-src 'none'; script-src 'sha256-${sha256(script)}'; style-src 'sha256-${sha256(styles)}'; connect-src 'none'; img-src data:; font-src 'none'; object-src 'none'; base-uri 'none'; form-action 'none'`;
  const total = result.findings.length;
  const high = result.findings.filter(finding => finding.priority === 'high').length;
  const affected = new Set(result.findings.flatMap(finding => finding.affectedIds)).size;
  const failures = result.findings.filter(finding => finding.kind === 'failure').length;
  const opportunities = result.findings.filter(finding => finding.kind === 'opportunity').length;
  const gaps = result.coverage.filter(item => item.state !== 'assessed').length;
  const assessed = result.coverage.filter(item => item.state === 'assessed').length;
  const siteName = options.siteName || result.siteUrl || 'Site audit';
  const client = options.clientName || 'Technical SEO audit';
  const dateValue = new Date(result.createdAt);
  const date = Number.isNaN(dateValue.getTime()) ? result.createdAt : dateValue.toLocaleDateString('en-US', { month: 'long', day: 'numeric', year: 'numeric', timeZone: 'UTC' });
  const maxCategory = Math.max(1, ...Object.keys(categories).map(category => result.findings.filter(finding => finding.category === category).length));
  const chart = Object.entries(categories).map(([key, label]) => {
    const items = result.findings.filter(finding => finding.category === key);
    const failed = items.filter(finding => finding.kind === 'failure').length;
    const other = items.length - failed;
    return `<div class="category-row"><span>${escape(label)}</span><svg viewBox="0 0 200 10" role="img" aria-label="${escape(label)}: ${number(items.length)} findings"><rect width="200" height="10" rx="3" fill="#eef2f6"/><rect width="${failed / maxCategory * 200}" height="10" rx="3" fill="#176d64"/><rect x="${failed / maxCategory * 200}" width="${other / maxCategory * 200}" height="10" fill="#a7c7bf"/></svg><strong>${number(items.length)}</strong></div>`;
  }).join('');
  const coverage = result.coverage.map(item => `<li><span class="coverage-state ${escape(item.state)}">${escape(item.state)}</span><strong>${escape(categories[item.category])}</strong><span class="coverage-reason">${escape(item.reason)}</span></li>`).join('');
  const summary = total ? `The snapshot contains <strong>${number(pages.length)} URLs</strong>. Analysis identified <strong>${number(total)} shared findings</strong> affecting <strong>${number(affected)} distinct URLs</strong>, including <strong>${number(high)} high-priority fixes</strong>.` : `The snapshot contains <strong>${number(pages.length)} URLs</strong>. No findings were identified in the checks assessed for this audit.`;
  const next = high ? 'Start with the high-priority fixes. Review the affected URLs and priority rationale before assigning each change.' : total ? 'Review the findings by category and site section. Opportunities and items needing review are labeled separately.' : 'Check crawl coverage before treating this result as a clean bill of health. Unassessed checks still need the data or action shown below.';
  const narrative = options.narrative?.executiveSummary ? `<div class="coverage"><div class="narrative-label">Assistant commentary</div><p class="narrative">${escape(options.narrative.executiveSummary)}</p><p class="stat-note">Interpretation supplied by your assistant. Counts, evidence, and priorities below are computed from the snapshot.</p></div>` : '';
  const findingsCsv = csv([['Finding ID', 'Priority', 'Category', 'Kind', 'Confidence', 'Title', 'Affected URLs', 'Section', 'Summary', 'Remediation', 'Priority rationale', 'Unique inlinks', 'Search clicks', 'Evidence'], ...result.findings.map(finding => [finding.id, finding.priority, finding.category, finding.kind, finding.confidence, finding.title, finding.affectedCount, finding.section, finding.summary, finding.remediation, finding.priorityReason, finding.inlinkTotal, finding.searchClicks, JSON.stringify(finding.evidence)])]);
  const urlsCsv = csv([['ID', 'URL', 'Section', 'Status code', 'Content type', 'Indexability', 'Indexability reason', 'Canonical', 'Canonical count', 'Title', 'Title count', 'Description', 'Description count', 'H1', 'H1 count', 'In sitemap', 'Redirect target', 'Unique inlinks', 'Search clicks'], ...pages.map(page => [page.id, page.url, page.section, page.statusCode, page.contentType, page.indexability, page.indexabilityReason, page.canonical, page.canonicalCount, page.title, page.titleCount, page.description, page.descriptionCount, page.h1, page.h1Count, page.inSitemap, page.redirectTarget, page.uniqueInlinks, page.searchClicks])]);
  const html = `<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="Content-Security-Policy" content="${escape(csp)}"><meta name="referrer" content="no-referrer"><title>${escape(siteName)} · JEStats technical SEO audit</title><style>${styles}</style></head>
<body>${result.provenance.source === 'fixture' ? '<div class="sample">SYNTHETIC SAMPLE · Demonstration data only · This report does not represent a live website audit</div>' : ''}
<header class="masthead"><div class="wrap masthead-inner"><div><div class="brand"><span class="brand-mark" aria-hidden="true">J</span>JEStats</div><div class="brand-sub">Technical SEO intelligence</div></div><div class="top-meta"><strong>${escape(client)}</strong>${escape(date)} · Offline report</div></div></header>
<main class="wrap"><section class="hero" aria-labelledby="report-heading"><div class="eyebrow">Evidence → shared fixes → action</div><h1 id="report-heading">A clear action plan for<br>${escape(siteName)}</h1><p class="hero-sub">Prioritized technical SEO findings, with the affected URLs, supporting evidence, and next steps in one place.</p><div class="hero-bottom"><div class="audit-meta"><span><strong>Site</strong> ${escape(result.siteUrl)}</span><span><strong>Crawl</strong> ${escape(result.sourceCrawlId)}</span><span><strong>Audit date</strong> ${escape(date)} UTC</span></div><a class="primary-link" href="#findings">Explore the action plan ↓</a></div></section>
<section class="stats" aria-label="Computed audit summary"><div class="stat"><div class="stat-label">URLs in snapshot</div><div class="stat-value" id="summary-page-count">${number(pages.length)}</div><div class="stat-note">Complete extracted dataset</div></div><div class="stat"><div class="stat-label">Shared findings</div><div class="stat-value" id="summary-finding-count">${number(total)}</div><div class="stat-note">${number(affected)} distinct URLs affected</div></div><div class="stat"><div class="stat-label">High-priority fixes</div><div class="stat-value high-text" id="summary-high-count">${number(high)}</div><div class="stat-note">Evidence and rationale included</div></div><div class="stat"><div class="stat-label">Checks with coverage gaps</div><div class="stat-value" id="summary-gap-count">${number(gaps)}</div><div class="stat-note">${number(assessed)} categories fully assessed</div></div></section>
<section class="overview-grid" aria-label="Executive overview and coverage"><div class="card"><div class="eyebrow">Executive overview</div><h2>From affected URLs to shared fixes</h2><p class="computed-summary">${summary}</p><p class="section-intro">${number(failures)} technical failure findings · ${number(opportunities)} opportunities · ${number(total - failures - opportunities)} informational findings. A URL can appear in more than one finding.</p><div class="emphasis">${next}</div>${narrative}</div><div class="card"><h2>Where the findings are</h2><p class="section-intro">Finding groups by category. Each group exposes the URLs behind it.</p><div class="legend"><span>Technical failures</span><span>Opportunities & information</span></div>${chart}<div class="coverage"><h3>Crawl coverage</h3><ul>${coverage}</ul></div></div></section>
<div id="loading" class="notice" role="status">Loading the bundled offline dataset…</div><noscript><div class="notice error">Enable JavaScript to filter findings and inspect the bundled evidence. The computed overview above remains available.</div></noscript>
<section id="interactive-report" hidden><section id="findings" class="workbench" aria-labelledby="findings-heading"><div class="section-head"><div><div class="eyebrow">The action plan</div><h2 id="findings-heading" tabindex="-1">Prioritized fixes, with the evidence</h2><p class="section-intro">Select a finding to see its scope, priority rationale, and recommended fix.</p></div><div class="actions"><button id="export-findings" type="button" class="button">Download findings CSV</button><button id="export-urls" type="button" class="button">Download all URLs CSV</button></div></div>
<div class="card table-card"><div class="filters"><label>Priority<select id="priority-filter"><option value="">All priorities</option><option value="high">High</option><option value="medium">Medium</option><option value="low">Low</option><option value="info">Informational</option></select></label><label>Category<select id="category-filter"><option value="">All categories</option>${Object.entries(categories).map(([key, label]) => `<option value="${key}">${escape(label)}</option>`).join('')}</select></label><label>Site section<select id="section-filter"><option value="__all__">All sections</option></select></label><button id="reset-filters" type="button" class="button">Reset filters</button></div><div class="table-scroll"><table aria-label="Prioritized findings"><thead><tr><th scope="col">Priority</th><th scope="col">Finding</th><th scope="col">Category</th><th scope="col">Affected URLs</th><th scope="col">Site section</th></tr></thead><tbody id="finding-body"></tbody></table></div><div id="no-findings" class="empty-state" hidden>No findings match these filters.</div><div class="pager"><span id="finding-count" aria-live="polite"></span><div class="pager-buttons"><button id="finding-prev" type="button" class="button" aria-label="Previous page of findings">← Previous</button><button id="finding-next" type="button" class="button" aria-label="Next page of findings">Next →</button></div></div></div>
<div id="detail-placeholder" class="detail-placeholder">Choose a finding above to inspect the affected URLs and plan the shared fix.</div>
<article id="finding-detail" class="card detail" hidden aria-labelledby="detail-title"><div class="detail-title-row"><div><div id="detail-id" class="finding-id"></div><h2 id="detail-title" tabindex="-1"></h2></div><button id="close-detail" type="button" class="button" aria-label="Close finding details">Close</button></div><div id="detail-chips" class="detail-chips"></div><div class="detail-grid"><div class="detail-copy"><p id="detail-summary"></p><h3>Recommended fix</h3><p id="detail-remediation"></p><h3>Why this priority</h3><p id="detail-priority-reason"></p><div id="detail-commentary-wrap" class="coverage" hidden><div class="narrative-label">Assistant commentary</div><p id="detail-commentary" class="narrative"></p><p class="stat-note">Assistant interpretation; computed evidence and priority remain unchanged.</p></div></div><div><div class="mini-stats"><div class="mini-stat">Affected URLs<strong id="detail-count"></strong></div><div class="mini-stat">Unique inlinks<strong id="detail-inlinks"></strong></div><div class="mini-stat">Search clicks<strong id="detail-clicks"></strong></div></div><p class="detail-section"><strong>Site section:</strong> <span id="detail-section"></span></p><h3>Supporting evidence</h3><dl id="detail-evidence" class="evidence"></dl></div></div><div class="urls-header"><h3>Affected URL evidence</h3><button id="export-finding" type="button" class="button">Download affected URLs CSV</button></div><div class="url-table"><div class="table-scroll"><table aria-label="Affected URLs for selected finding"><thead><tr id="url-header-row"><th scope="col">URL</th><th scope="col">Section</th><th scope="col">Status</th><th scope="col">Indexability</th><th scope="col">Unique inlinks</th></tr></thead><tbody id="url-body"></tbody></table></div><div class="pager"><span id="url-count" aria-live="polite"></span><div class="pager-buttons"><button id="url-prev" type="button" class="button" aria-label="Previous page of affected URLs">← Previous</button><button id="url-next" type="button" class="button" aria-label="Next page of affected URLs">Next →</button></div></div></div></article></section></section>
<footer class="footer"><div class="footer-row"><div><strong>JEStats</strong> · Technical SEO audit<br><span id="report-status" role="status">Computed facts from an immutable local snapshot. Interactive evidence loads locally.</span></div><div>Preset ${escape(result.provenance.preset)}<br>Plugin ${escape(result.provenance.pluginVersion)} · Report schema ${result.schemaVersion}</div></div><div class="provenance">Audit ${escape(result.id)} · Snapshot SHA-256 ${escape(result.provenance.snapshotHash)} · Created ${escape(result.createdAt)}</div></footer></main><script id="report-script">${script}</script></body></html>`;
  return { html, findingsCsv, urlsCsv };
}
